// This file was generated by Prisma, and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import "dotenv/config";
import { defineConfig } from "prisma/config";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";

let migrationUrl = process.env["DIRECT_URL"] || process.env["DATABASE_URL"];
if (migrationUrl) {
  let url: URL;
  try { url = new URL(migrationUrl); }
  catch { throw new Error("Database URL is invalid. Check backend environment configuration."); }
  if (/(?:^|\.)supabase\.(?:co|com)$/.test(url.hostname)) {
    // Prisma CLI memakai parameter TLS connector sendiri, berbeda dari pg.
    url.searchParams.set("sslmode", "require");
    url.searchParams.set("sslaccept", "strict");
    const caFile = process.env["DATABASE_SSL_CA_FILE"];
    if (caFile) {
      url.searchParams.set("sslcert", resolve(fileURLToPath(new URL(".", import.meta.url)), caFile));
    }
    migrationUrl = url.toString();
  }
}

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    // Opsional untuk koneksi migration terpisah; runtime tetap DATABASE_URL.
    url: migrationUrl,
  },
});
